INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 8, 309, 11, 0, 103311, "新春初笑いのネタをつくってきたべ！\n誰か聞いていかねえか？", 0, 0.5, 309001, 0);
