INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 8, 310, 11, 0, 103411, "みんな～、あけおめ～！\nなんちゃって。ヒック。", 0, 0.5, 310011, 0);
