INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 8, 311, 11, 0, 102711, "この広い会場のどこかに\nあのおかたの存在を感じますわ……", 0, 0.5, 311002, 0);
