INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 8, 312, 11, 0, 101831, "素敵な新年会ね～\n他の学校の人たちも来ているようだし\nお話を伺いに行こうかしら？", 0, 0.5, 312001, 0);
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0.2, 1, 312, 3, "", 101831, "nop_talk_joy1", "", "", 312002, "");
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES ("", "", 312, 91, "", 312001, "", "", "", 312003, "");
