INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 8, 312, 11, 0, 101611, "見て見てミサキっち！\nあそこの料理すっごく美味しそう！", 0, 0.5, 312005, 0);
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0.2, 1, 312, 3, "", 101611, "nop_talk_surprise_kira", "", "", 312006, "");
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES ("", "", 312, 91, "", 312005, "", "", "", 312007, "");
