INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES ("", "", 312, 91, "", 312009, "", "", "", 312013, "");
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0.2, 1, 312, 3, "", 105011, "nop_idle_sad", "", "", 312014, 1);
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 8, 313, 11, 0, 105331, "立派な新年会ではないか。\n我々もこの場に相応しく\n振る舞わなければな！", 0, 0.5, 313001, 0);
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0.2, 0, 313, 3, "nop_13_monica_talk_doya_loop", 105331, "nop_13_monica_talk_doya", 0.2, "", 313002, 1);
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES ("", "", 313, 91, "", 313001, "", "", "", 313003, "");
