INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 8, 313, 11, 0, 100811, "新年会でもボクは美しいね。\nああ、会場中の視線が\n集まってるようだよ。", 0, 0.5, 313009, 0);
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0.2, 1, 313, 3, "", 100811, "nop_talk_thinking", "", "", 313010, "");
