INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 8, 313, 11, 0, 104511, "会場中の視線……\nああ、蔑みの視線がクウカに……\nぐふふふ……", 0, 0.5, 313013, 0);
INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0.2, 1, 313, 3, "", 104511, "nop_13_kuka_talk_memory1", "", "", 313014, "");
