INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 8, 313, 11, 0, 105511, "大きな会場……\n先輩はどこにいるのかな？", 0, 0.5, 313017, 0);
