INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 8, 506, 11, 1, 103731, "クリスティーナ！\nあなたはいったいどの面下げて\n私たちの前に……", 0, 0.5, 506013, 0);
