INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 8, 511, 11, 1, 100911, "うむ！\n我らの破壊の協奏曲でいかなる状況も\n吹き飛ばしてやったというのに！", 0, 0.5, 511036, 0);
