INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 5, 513, 11, 1, 105331, "これだけの人数に会うのは\nギルドレースの祝賀会以来か。\n貴公の人望にはおそれいるな。", 0, 0.5, 513053, 0);
