INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 6, 513, 11, 1, 100811, "この場にいるたくさんの人たちに\nボクの美しさを届けられるのは\nキミのおかげだよ。", 0, 0.5, 513060, 0);
