INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 6, 513, 11, 1, 105331, "新年といういい機会だ。\n今年の抱負を発表しようじゃないか。", 0, 0.5, 513077, 0);
